function validate([digits]) {
  if (!Array.isArray(digits) || digits.length < 1 || digits.length > 10000) return 'digits needs 1 to 10^4 values.';
  if (digits.some(d => !Number.isInteger(d) || d < 0 || d > 9)) return 'Each entry is a digit from 0 to 9.';
  return null;
}

