function largestMultipleOfThree(digits) {
  const count = new Array(10).fill(0);
  let total = 0;
  for (const digit of digits) {
    count[digit]++;
    total += digit;
  }

  const removeSmallest = (remainder, times) => {
    for (let digit = remainder; digit <= 9 && times > 0; digit += 3) {
      while (count[digit] > 0 && times > 0) {
        count[digit]--;
        times--;
      }
    }
    return times === 0;
  };

  const remainder = total % 3;
  if (remainder !== 0 && !removeSmallest(remainder, 1)) {
    removeSmallest(3 - remainder, 2);
  }

  let result = '';
  for (let digit = 9; digit >= 0; digit--) {
    result += String(digit).repeat(count[digit]);
  }
  if (result[0] === '0') {
    return '0';
  }
  return result;
}

