function largestMultipleOfThree(digits) {
  // DP over the digits in descending order: best[r] is the best digit string (longest, then
  // lexicographically largest) using some of the digits seen so far with digit sum % 3 === r.
  const sorted = digits.slice().sort((a, b) => b - a);
  const better = (a, b) => b === null || a.length > b.length || (a.length === b.length && a > b);
  let best = ['', null, null];
  for (const d of sorted) {
    const next = best.slice();
    for (let r = 0; r < 3; r++) {
      if (best[r] === null) continue;
      const candidate = best[r] + d;
      const target = (r + d) % 3;
      if (better(candidate, next[target])) next[target] = candidate;
    }
    best = next;
  }
  if (best[0] === '') return '';
  return best[0][0] === '0' ? '0' : best[0];
}

